Text::CStringNN IO::BTUtil::GetManufacturerName(UInt16 manuf)
{
	IntOS i = 0;
	IntOS j = (sizeof(compId) / sizeof(compId[0])) - 1;
	IntOS k;
	while (i <= j)
	{
		k = (i + j) >> 1;
		if (compId[k].id > manuf)
		{
			j = k - 1;
		}
		else if (compId[k].id < manuf)
		{
			i = k + 1;
		}
		else
		{
			return Text::CStringNN(compId[k].name, compId[k].nameLen);
		}
	}
	return CSTR("Unknown");
}

Text::CString IO::BTUtil::CompanyGetName(UInt16 manuf)
{
	IntOS i = 0;
	IntOS j = (sizeof(compId) / sizeof(compId[0])) - 1;
	IntOS k;
	while (i <= j)
	{
		k = (i + j) >> 1;
		if (compId[k].id > manuf)
		{
			j = k - 1;
		}
		else if (compId[k].id < manuf)
		{
			i = k + 1;
		}
		else
		{
			return Text::CStringNN(compId[k].name, compId[k].nameLen);
		}
	}
	return nullptr;
}

void IO::BTUtil::GetAddrText(NN<Text::StringBuilderUTF8> sb, UnsafeArray<const UInt8> addr)
{
	sb->AppendHex8(addr[5]);
	sb->AppendC(UTF8STRC(":"));
	sb->AppendHex8(addr[4]);
	sb->AppendC(UTF8STRC(":"));
	sb->AppendHex8(addr[3]);
	sb->AppendC(UTF8STRC(":"));
	sb->AppendHex8(addr[2]);
	sb->AppendC(UTF8STRC(":"));
	sb->AppendHex8(addr[1]);
	sb->AppendC(UTF8STRC(":"));
	sb->AppendHex8(addr[0]);
}

UInt64 IO::BTUtil::GetAddrMAC(UnsafeArray<const UInt8> addr)
{
	UInt8 buff[8];
	buff[0] = addr[0];
	buff[1] = addr[1];
	buff[2] = addr[2];
	buff[3] = addr[3];
	buff[4] = addr[4];
	buff[5] = addr[5];
	buff[6] = 0;
	buff[7] = 0;
	return ReadLUInt64(buff);
}

Text::CStringNN IO::BTUtil::GetUUIDName(UInt16 uuid)
{
	IntOS i = 0;
	IntOS j = (sizeof(uuids) / sizeof(uuids[0])) - 1;
	IntOS k;
	while (i <= j)
	{
		k = (i + j) >> 1;
		if (uuids[k].id > uuid)
		{
			j = k - 1;
		}
		else if (uuids[k].id < uuid)
		{
			i = k + 1;
		}
		else
		{
			return Text::CStringNN(uuids[k].name, uuids[k].nameLen);
		}
	}
	return CSTR("Unknown");
}

void IO::BTUtil::GetServiceName(NN<Text::StringBuilderUTF8> sb, NN<Data::UUID> serviceUUID)
{
	sb->Append(GetUUIDName((UInt16)serviceUUID->GetTimeLow()));
	sb->AppendC(UTF8STRC(" ("));
	serviceUUID->ToString(sb);
	sb->AppendC(UTF8STRC(")"));
}

Text::CStringNN IO::BTUtil::CoreVersionGetName(UInt8 coreVersion)
{
	switch (coreVersion)
	{
	case 0x00:
		return CSTR("Bluetooth® Core Specification 1.0b (Withdrawn)");
	case 0x01:
		return CSTR("Bluetooth® Core Specification 1.1 (Withdrawn)");
	case 0x02:
		return CSTR("Bluetooth® Core Specification 1.2 (Withdrawn)");
	case 0x03:
		return CSTR("Bluetooth® Core Specification 2.0+EDR (Withdrawn)");
	case 0x04:
		return CSTR("Bluetooth® Core Specification 2.1+EDR (Withdrawn)");
	case 0x05:
		return CSTR("Bluetooth® Core Specification 3.0+HS (Withdrawn)");
	case 0x06:
		return CSTR("Bluetooth® Core Specification 4.0 (Withdrawn)");
	case 0x07:
		return CSTR("Bluetooth® Core Specification 4.1 (Deprecated)");
	case 0x08:
		return CSTR("Bluetooth® Core Specification 4.2");
	case 0x09:
		return CSTR("Bluetooth® Core Specification 5.0");
	case 0x0A:
		return CSTR("Bluetooth® Core Specification 5.1");
	case 0x0B:
		return CSTR("Bluetooth® Core Specification 5.2");
	case 0x0C:
		return CSTR("Bluetooth® Core Specification 5.3");
	case 0x0D:
		return CSTR("Bluetooth® Core Specification 5.4");
	default:
		return CSTR("Unknown");
	}
}

Text::CStringNN IO::BTUtil::DIACSGetName(UInt32 diacs)
{
	switch (diacs)
	{
	case 0x9E8B00:
		return CSTR("Limited Inquiry Access Code (LIAC)");
	case 0x9E8B33:
		return CSTR("General Inquiry Access Code (GIAC)");
	default:
		return CSTR("Unknown");
	}
}

